mapper.update:
UPDATE PDA_DEVICE_ACTIVITY
   SET LOGOUT_AT = SYSDATE
 WHERE UNIQUE_ID = #{uniqueId}

mapper.select:
SELECT UNIQUE_ID, STORE_CD, USER_ID, LAST_ACTIVE_AT, LOGOUT_AT
  FROM PDA_DEVICE_ACTIVITY
 WHERE STORE_CD = #{storeCd}
   AND LAST_ACTIVE_AT >= #{activeSince}
 ORDER BY CASE WHEN USER_ID = #{userId} THEN 0 ELSE 1 END,
          LAST_ACTIVE_AT DESC

SELECT UNIQUE_ID, STORE_CD, USER_ID, LAST_ACTIVE_AT, LOGOUT_AT
  FROM PDA_DEVICE_ACTIVITY
 WHERE UNIQUE_ID = #{uniqueId}
